import pytest
from candidate import strange_sort_list


class TestStrangeSortList:
    def test_normal_case_four_elements(self):
        assert strange_sort_list([1, 2, 3, 4]) == [1, 4, 2, 3]

    def test_normal_case_unsorted_input(self):
        assert strange_sort_list([4, 1, 3, 2]) == [1, 4, 2, 3]

    def test_normal_case_reverse_sorted(self):
        assert strange_sort_list([4, 3, 2, 1]) == [1, 4, 2, 3]

    def test_normal_case_three_elements(self):
        assert strange_sort_list([3, 1, 2]) == [1, 3, 2]

    def test_normal_case_two_elements(self):
        assert strange_sort_list([2, 1]) == [1, 2]

    def test_normal_case_two_elements_already_sorted(self):
        assert strange_sort_list([1, 2]) == [1, 2]

    def test_normal_case_single_element(self):
        assert strange_sort_list([42]) == [42]

    def test_normal_case_empty_list(self):
        assert strange_sort_list([]) == []

    def test_normal_case_all_same_elements(self):
        assert strange_sort_list([5, 5, 5, 5]) == [5, 5, 5, 5]

    def test_normal_case_all_same_single(self):
        assert strange_sort_list([7]) == [7]

    def test_normal_case_negative_numbers(self):
        assert strange_sort_list([-3, -1, -2]) == [-3, -1, -2]

    def test_normal_case_mixed_positive_negative(self):
        assert strange_sort_list([0, -1, 1]) == [-1, 1, 0]

    def test_normal_case_zero_mixed(self):
        assert strange_sort_list([0, -5, 3, -2]) == [-5, 3, -2, 0]

    def test_normal_case_duplicates(self):
        assert strange_sort_list([1, 3, 2, 2]) == [1, 3, 2, 2]

    def test_normal_case_five_elements(self):
        assert strange_sort_list([5, 1, 3, 2, 4]) == [1, 5, 2, 4, 3]

    def test_normal_case_six_elements(self):
        assert strange_sort_list([6, 1, 5, 2, 4, 3]) == [1, 6, 2, 5, 3, 4]

    def test_normal_case_large_values(self):
        assert strange_sort_list([1000000, -1000000, 500000, -500000]) == [-1000000, 1000000, -500000, 500000]

    def test_normal_case_negative_and_zero(self):
        assert strange_sort_list([-1, 0, -2]) == [-2, 0, -1]

    def test_normal_case_positive_and_zero(self):
        assert strange_sort_list([0, 1, 0]) == [0, 1, 0]

    def test_normal_case_all_zeros(self):
        assert strange_sort_list([0, 0, 0]) == [0, 0, 0]

    def test_normal_case_seven_elements(self):
        assert strange_sort_list([7, 1, 6, 2, 5, 3, 4]) == [1, 7, 2, 6, 3, 5, 4]

    def test_normal_case_ten_elements(self):
        lst = [10, 1, 9, 2, 8, 3, 7, 4, 6, 5]
        assert strange_sort_list(lst) == [1, 10, 2, 9, 3, 8, 4, 7, 5, 6]

    def test_input_list_is_mutated(self):
        lst = [1, 2, 3, 4]
        strange_sort_list(lst)
        assert lst == []

    def test_none_input_returns_empty_list(self):
        assert strange_sort_list(None) == []

    def test_single_negative(self):
        assert strange_sort_list([-1]) == [-1]

    def test_two_negative_numbers(self):
        assert strange_sort_list([-1, -3]) == [-3, -1]

    def test_mixed_duplicates(self):
        assert strange_sort_list([2, 2, 1, 3]) == [1, 3, 2, 2]

    def test_already_strange_sorted(self):
        assert strange_sort_list([1, 4, 2, 3]) == [1, 4, 2, 3]

    def test_returns_list_type(self):
        assert isinstance(strange_sort_list([1, 2, 3]), list)

    def test_returns_empty_list_type(self):
        result = strange_sort_list([])
        assert isinstance(result, list)
        assert len(result) == 0

    def test_preserves_element_count(self):
        original = [5, 3, 8, 1, 9, 2, 7, 4, 6]
        result = strange_sort_list(original[:])
        assert len(result) == len(original)
        assert sorted(result) == sorted(original)

    def test_with_floats(self):
        assert strange_sort_list([1.5, 3.2, 0.1, 2.8]) == [0.1, 3.2, 1.5, 2.8]

    def test_mixed_int_and_float(self):
        assert strange_sort_list([1, 3.0, 2, 4.5]) == [1, 4.5, 2, 3.0]

    def test_tuple_input_raises_attribute_error(self):
        with pytest.raises(AttributeError):
            strange_sort_list((1, 2, 3))

    def test_integer_input_raises_type_error(self):
        with pytest.raises(TypeError):
            strange_sort_list(123)

    def test_string_input_raises_type_error(self):
        with pytest.raises((TypeError, AttributeError)):
            strange_sort_list("hello")

    def test_large_list(self):
        lst = list(range(1, 101))
        result = strange_sort_list(lst[:])
        assert len(result) == 100
        assert sorted(result) == list(range(1, 101))
        assert result[0] == 1
        assert result[1] == 100
        assert result[2] == 2
        assert result[3] == 99

    def test_all_negative_list(self):
        assert strange_sort_list([-5, -1, -3, -2, -4]) == [-5, -1, -3, -2, -4]

    def test_negative_and_positive_mixed_duplicates(self):
        assert strange_sort_list([-1, 1, -1, 1]) == [-1, 1, -1, 1]

    def test_three_elements_unsorted(self):
        assert strange_sort_list([10, 1, 5]) == [1, 10, 5]

    def test_four_elements_with_duplicates(self):
        assert strange_sort_list([3, 1, 3, 1]) == [1, 3, 1, 3]
